
.zx-line {
  margin: 0 0 6px;
}

.zx-dim {
  color: #6f6659;
}

.zx-receipt {
  margin: 0 0 8px;
  padding: 5px 9px;
  border-left: 2px solid #5f8a6d;
  background: #f3f7f3;
  font-size: 11.5px;
  color: #3f6b4d;
}

.zx-site {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid #e2ddd3;
  border-radius: 5px;
  background: #fffdf9;
}

.zx-site-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid #efeae1;
}

.zx-site-name {
  font-size: 13px;
  font-weight: 600;
}

.zx-site-tag {
  font-size: 11px;
  color: #6f6659;
}

.zx-job {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
}

.zx-job-off {
  opacity: 0.55;
}

.zx-job-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}

.zx-job-name {
  font-size: 12.5px;
  font-weight: 600;
}

.zx-job-meta {
  font-size: 11px;
  color: #8a6a3a;
}

.zx-job-desc {
  font-size: 11px;
  color: #6f6659;
}

.zx-btn {
  flex-shrink: 0;
  min-width: 78px;
  padding: 6px 10px;
  border: 1px solid #c9b79b;
  border-radius: 4px;
  background: #f0e6d6;
  color: #4a4238;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.zx-btn:hover:not(:disabled) {
  background: #e8dbc6;
}

.zx-btn:disabled {
  border-color: #ddd6c9;
  background: #f2efe9;
  color: #9a9186;
  cursor: default;
}
