
.zx-frame {
  padding: 10px;
  border: 1px solid #d8d2c8;
  border-radius: 5px;
  background: #fffdf9;
}

.zx-frame-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-size: 11.5px;
  color: #6f6659;
}

.zx-frame-name {
  font-size: 12.5px;
  font-weight: 600;
  color: #33302b;
}

.zx-frame-prog,
.zx-frame-time {
  font-variant-numeric: tabular-nums;
}

.zx-frame-quit {
  margin-left: auto;
  padding: 2px 8px;
  border: 1px solid #ddd6c9;
  border-radius: 3px;
  background: transparent;
  color: #6f6659;
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.zx-frame-bar {
  height: 3px;
  margin: 6px 0 10px;
  border-radius: 2px;
  background: #ece7dd;
  overflow: hidden;
}

.zx-frame-fill {
  height: 100%;
  background: #b98a3c;
  transition: width 1s linear;
}

.zx-frame-tip {
  margin: 8px 0 0;
  font-size: 11.5px;
  min-height: 17px;
}

.zx-dim {
  color: #6f6659;
}
