
.zx-block {
  margin-bottom: 14px;
}

.zx-block-head {
  padding-bottom: 5px;
  border-bottom: 1px solid #e2ddd3;
  font-size: 12.5px;
  font-weight: 600;
}

.zx-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 0;
  border-bottom: 1px dashed #efeae1;
  font-size: 12px;
  color: #6f6659;
}

.zx-strong {
  color: #33302b;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.zx-track {
  height: 6px;
  margin-top: 8px;
  border-radius: 3px;
  background: #e5e0d6;
  overflow: hidden;
}

.zx-fill {
  height: 100%;
  background: #5f8a6d;
  transition: width 0.3s ease;
}

.zx-fill-warn {
  background: #b06a6a;
}

.zx-line {
  margin: 8px 0 0;
  font-size: 11.5px;
}

.zx-dim {
  color: #6f6659;
}
