
.zx-sis-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid #e2ddd3;
}

.zx-sis-name {
  font-size: 13px;
  font-weight: 600;
}

.zx-sis-age {
  margin-left: 8px;
  font-size: 11.5px;
  color: #6f6659;
}

.zx-sis-word {
  font-size: 11px;
  color: #6f6659;
}

.zx-ill {
  margin-top: 8px;
  padding: 5px 9px;
  border-left: 2px solid #b06a6a;
  background: #faf3f1;
  font-size: 11.5px;
  color: #7a4b45;
}

.zx-did {
  margin: 8px 0 0;
  font-size: 11.5px;
  color: #5f8a6d;
}

.zx-block {
  margin-top: 12px;
}

.zx-block-head {
  padding-bottom: 5px;
  border-bottom: 1px solid #e2ddd3;
  font-size: 12.5px;
  font-weight: 600;
}

.zx-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.zx-chip {
  padding: 6px 10px;
  border: 1px solid #d8d2c8;
  border-radius: 4px;
  background: #f7f4ee;
  color: #33302b;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.zx-chip:hover:not(:disabled) {
  border-color: #b98a3c;
  background: #f0e6d6;
}

.zx-chip:disabled {
  opacity: 0.45;
  cursor: default;
}

.zx-chip-on {
  border-color: #b98a3c;
  background: #efe2cc;
  font-weight: 600;
}

.zx-chip-n {
  color: #6f6659;
  font-size: 11px;
}

.zx-line {
  margin: 8px 0 0;
  font-size: 11.5px;
}

.zx-dim {
  color: #6f6659;
}
