
.zx-panel {
  box-sizing: border-box;
  width: 100%;
  padding: 10px 12px 12px;
  border: 1px solid #d8d2c8;
  border-radius: 6px;
  background: #f7f4ee;
  color: #33302b;
  font-family: 'PingFang SC', 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
  font-size: 12.5px;
  line-height: 1.5;
  text-align: left;
}

.zx-panel * {
  box-sizing: border-box;
}

.zx-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid #e2ddd3;
}

.zx-clock {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.zx-clock-date {
  font-size: 12px;
  color: #6f6659;
}

.zx-clock-time {
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #4a4238;
}

.zx-head-right {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.zx-money {
  font-size: 13px;
  font-weight: 600;
  color: #8a6a3a;
  font-variant-numeric: tabular-nums;
}

.zx-day {
  font-size: 11.5px;
  color: #6f6659;
}

.zx-bars {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  padding: 8px 0 4px;
}

.zx-bar {
  min-width: 0;
}

.zx-bar-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.zx-bar-name {
  font-size: 11px;
  color: #6f6659;
}

.zx-bar-val {
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.zx-bar-track {
  height: 5px;
  margin-top: 3px;
  border-radius: 3px;
  background: #e5e0d6;
  overflow: hidden;
}

.zx-bar-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease;
}

.zx-fill-hunger {
  background: #b98a3c;
}

.zx-fill-mood {
  background: #a4708f;
}

.zx-fill-health {
  background: #5f8a6d;
}

.zx-tabs {
  display: flex;
  gap: 4px;
  margin-top: 8px;
  border-bottom: 1px solid #e2ddd3;
}

.zx-tab {
  padding: 6px 14px;
  border: 1px solid transparent;
  border-bottom: none;
  border-radius: 4px 4px 0 0;
  background: transparent;
  color: #6f6659;
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
}

.zx-tab:hover {
  color: #33302b;
}

.zx-tab-on {
  border-color: #d8d2c8;
  background: #fffdf9;
  color: #33302b;
  font-weight: 600;
}

.zx-body {
  padding-top: 10px;
}

@media (max-width: 480px) {
  .zx-head {
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
  }
  .zx-tab {
    padding: 6px 10px;
  }
}
