
.zx-wallet {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 6px 10px;
  border: 1px solid #e2ddd3;
  border-radius: 4px;
  background: #fffdf9;
  font-size: 12px;
  color: #6f6659;
}

.zx-wallet-num {
  font-size: 14px;
  font-weight: 600;
  color: #8a6a3a;
  font-variant-numeric: tabular-nums;
}

.zx-buy-back {
  margin: 8px 0 0;
  font-size: 11.5px;
  color: #5f8a6d;
}

.zx-shop-group {
  margin-top: 12px;
}

.zx-shop-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-bottom: 5px;
  border-bottom: 1px solid #e2ddd3;
}

.zx-shop-name {
  font-size: 12.5px;
  font-weight: 600;
}

.zx-shop-note {
  font-size: 11px;
  color: #6f6659;
}

.zx-good {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  border-bottom: 1px dashed #efeae1;
}

.zx-good-off {
  opacity: 0.5;
}

.zx-good-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}

.zx-good-name {
  font-size: 12.5px;
  font-weight: 600;
}

.zx-good-note {
  font-size: 11px;
  color: #6f6659;
}

.zx-good-stock {
  font-size: 11px;
  color: #8a6a3a;
}

.zx-good-side {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.zx-good-price {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: #4a4238;
}

.zx-btn {
  min-width: 62px;
  padding: 5px 10px;
  border: 1px solid #c9b79b;
  border-radius: 4px;
  background: #f0e6d6;
  color: #4a4238;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.zx-btn:hover:not(:disabled) {
  background: #e8dbc6;
}

.zx-btn:disabled {
  border-color: #ddd6c9;
  background: #f2efe9;
  color: #9a9186;
  cursor: default;
}
